cat > astro.config.mjs <<'EOF'
// @ts-check
import { defineConfig } from "astro/config";

import preact from "@astrojs/preact";

// https://astro.build/config
export default defineConfig({
  // Public URL of the deployed site. Used for absolute links such as the RSS feed.
  // Set SITE_URL at build time (see fly.toml [build.args]); falls back for local dev.
  site: process.env.SITE_URL || "https://example.com",
  integrations: [preact()],
});
EOF
cat > Caddyfile <<'EOF'
# Serves the static Astro build. TLS is terminated by the Fly.io edge proxy,
# so Caddy only speaks plain HTTP on the internal port.
{
	admin off
	auto_https off
	# Fly's proxy connects from private addresses; trust it so logs show the real client IP.
	servers {
		trusted_proxies static private_ranges
		client_ip_headers Fly-Client-IP X-Forwarded-For
	}
}

:8080 {
	# One JSON line per request on stdout -> visible via `fly logs`.
	log {
		output stdout
		format json
	}

	# Health check endpoint used by fly.toml.
	handle /healthz {
		respond "ok" 200
	}

	root * /srv
	encode zstd gzip

	header {
		Strict-Transport-Security "max-age=31536000"
		X-Content-Type-Options "nosniff"
		Referrer-Policy "strict-origin-when-cross-origin"
		X-Frame-Options "DENY"
		-Server
	}

	# Astro's hashed build assets never change; cache them forever.
	@immutable path /_astro/*
	header @immutable Cache-Control "public, max-age=31536000, immutable"

	file_server

	handle_errors {
		@notfound expression {err.status_code} == 404
		handle @notfound {
			rewrite * /404.html
			file_server
		}
		respond "{err.status_code} {err.status_text}"
	}
}
EOF
cat > Dockerfile <<'EOF'
# syntax=docker/dockerfile:1

# ---- Build the static site ----
FROM node:22-alpine AS build
WORKDIR /app

COPY package.json package-lock.json ./
RUN npm ci

COPY . .
# Public URL of the site, baked into the RSS feed and absolute links.
ARG SITE_URL
ENV SITE_URL=${SITE_URL}
RUN npm run build

# ---- Serve it ----
FROM caddy:2-alpine
COPY Caddyfile /etc/caddy/Caddyfile
COPY --from=build /app/dist /srv
EXPOSE 8080
# The caddy image's default CMD runs /etc/caddy/Caddyfile.
EOF
cat > .dockerignore <<'EOF'
node_modules
dist
.astro
.git
.github
.vscode
.env
.env.*
npm-debug.log*
EOF
